//2010.03.11 김봉석 대리 요청
// 접수상태 전체 선택시 모두 체크 되도록
scwin.fn_allCheck_2 = function() {
    var checkArray;
    if (scwin.gDepCdCheck == 'Y') {
        checkArray = [chb_stat_00, chb_stat_30, chb_stat_40, chb_stat_10];
    } else {
        checkArray = [chb_stat_00, chb_stat_30, chb_stat_40];
    }
    if (chb_stat_99.checked == true) {
        for (var i = 0; i < checkArray.length; i++) {
            checkArray[i].setValue(1);
        }
    }
    if (chb_stat_99.checked == false) {
        for (var i = 0; i < checkArray.length; i++) {
            checkArray[i].setValue(0);
        }
    }
};




//2010.03.11 김봉석 대리 요청
// 접수상태 전체 선택시 모두 체크 되도록
scwin.fn_allCheck_3 = function() {
    var checkArray = [chb_bzstat_20, chb_bzstat_22];
    if (chb_bzstat_99.checked == true) {
        for (var i = 0; i < checkArray.length; i++) {
            checkArray[i].setValue(1);
        }
    }
    if (chb_bzstat_99.checked == false) {
        for (var i = 0; i < checkArray.length; i++) {
            checkArray[i].setValue(0);
        }
    }
};
scwin.fn_getCondValue = function(pCnt, pVal, vCode) {
    if (pCnt > 0) {
        pVal += "," + vCode + "";
    } else {
        pVal = vCode;
    }
    return pVal;
};
scwin.fn_getCondition_2 = function() {
    var vStatCnt = 0;
    var vStatCond = '';
    if (chb_stat_99.checked == true) {
        vStatCond = '';
        vStatCnt++;
    } else {
        if (chb_stat_00.checked == true) {
            vStatCond = scwin.fn_getCondValue(vStatCnt, vStatCond, '00');
            vStatCnt++;
        }
        if (chb_stat_30.checked == true) {
            vStatCond = scwin.fn_getCondValue(vStatCnt, vStatCond, '30');
            vStatCnt++;
        }
        if (chb_stat_40.checked == true) {
            vStatCond = scwin.fn_getCondValue(vStatCnt, vStatCond, '40');
            vStatCnt++;
        }
        if (scwin.gDepCdCheck == 'Y') {
            if (chb_stat_10.checked == true) {
                vStatCond = scwin.fn_getCondValue(vStatCnt, vStatCond, '10');
                vStatCnt++;
            }
        }
    }
    return vStatCond;
};
scwin.fn_getCondition_3 = function() {
    var vStatCnt = 0;
    var vStatCond = '';
    if (chb_bzstat_99.checked == true) {
        vStatCond = '';
        vStatCnt++;
    } else {
        if (chb_bzstat_20.checked == true) {
            vStatCond = scwin.fn_getCondValue(vStatCnt, vStatCond, '20');
            vStatCnt++;
        }
        if (chb_bzstat_22.checked == true) {
            vStatCond = scwin.fn_getCondValue(vStatCnt, vStatCond, '22');
            vStatCnt++;
        }
    }
    return vStatCond;
};
scwin.fn_Search = function() {
    if (MaxTab_01.getSelectedTabIndex() == 1) {
        var url = "/ListedReceive.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listUnreceiveRequest&inputMessageId=RECV_LSTRCV_INOUT";
        url += "&DEP_CD=" + $c.stf.getObjectValue(cmb_DEP_CD_1);
        url += "&EMP_NO=" + $c.stf.getObjectValue(cmb_EMP_NO_1);
        url += "&UP_DEP_CD=" + js_belngdepcd;
        url += "&LD_MKT_TP_CD=" + scwin.gLdMktTp;
        //alert("vListMdCd :"+vListMdCd);
        dts_List_1.DataID = encodeURI(url);
        dts_List_1.Reset();
        //ShowWin(grd_List_1); 

    } else if (MaxTab_01.getSelectedTabIndex() == 2) {
        var cond = scwin.fn_getCondition_2();
        //alert ('[cond]'+cond);

        if (chb_main_yn.checked == false && chb_atch_yn.checked == false) {
            $c.win.alert("제출유형은 한개이상 선택하십시오.");
            chb_main_yn.focus();
            return;
        }
        var url = "/ListedReceive.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listReceipt&inputMessageId=RECV_LSTRCV_INOUT";
        url += "&ISUR_CD=" + $c.stf.getObjectValue(txb_ISUR_CD_2);
        url += "&FORM_CD=" + $c.stf.getObjectValue(cmb_FORM_CD);
        url += "&ACPT_SDATE=" + $c.stf.getObjectValue(edt_AcptSDate);
        url += "&ACPT_EDATE=" + $c.stf.getObjectValue(edt_AcptEDate);
        url += "&DEP_CD=" + $c.stf.getObjectValue(cmb_DEP_CD_2);
        url += "&EMP_NO=" + $c.stf.getObjectValue(cmb_EMP_NO_2);
        url += "&DISCLS_PROCS_STAT_CD=" + scwin.fn_getCondition_2();
        //url += "&DISCLS_PROCS_STAT_CD=" + getObjectValue(cmb_LIST_PROCS_STAT_CD);
        url += "&UP_DEP_CD=" + js_belngdepcd;
        url += "&LD_MKT_TP_CD=" + scwin.gLdMktTp;
        url += "&MAIN_YN=" + $c.stf.getObjectValue(chb_main_yn);
        url += "&ATTCH_YN=" + $c.stf.getObjectValue(chb_atch_yn);
        //alert("vListMdCd :"+vListMdCd);
        dts_List_2.DataID = encodeURI(url);
        dts_List_2.Reset();
        $c.cm.ShowWin(grd_List_2);
    } else if (MaxTab_01.getSelectedTabIndex() == 3) {
        var url = "/ListedReceive.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listBzProcsStat&inputMessageId=BZ_PROCS_STAT_LIST_OUT";
        url += "&SS_DEP_CD=" + js_dep_cd;
        url += "&ISUR_CD=" + $c.stf.getObjectValue(txb_ISUR_CD_3);
        url += "&LIST_BZ_TP_CD=" + $c.stf.getObjectValue(cmb_LIST_BZ_TP_CD);
        url += "&BZ_SDATE=" + $c.stf.getObjectValue(edt_BzSDate);
        url += "&BZ_EDATE=" + $c.stf.getObjectValue(edt_BzEDate);
        url += "&DEP_CD=" + $c.stf.getObjectValue(cmb_DEP_CD_3);
        url += "&EMP_NO=" + $c.stf.getObjectValue(cmb_EMP_NO_3);
        url += "&LIST_PROCS_STAT_CD=" + scwin.fn_getCondition_3();
        url += "&LD_MKT_TP_CD=" + scwin.gLdMktTp;

        //alert("vListMdCd :"+vListMdCd);
        dts_List_3.DataID = encodeURI(url);
        dts_List_3.Reset();
        $c.cm.ShowWin(grd_List_3);
    }
};



// 클릭된 값 변수에 셋팅
scwin.fn_OpenDetail = function(row, colid) {
    scwin.fn_setContnId(row);
    if (colid == "FORM_KOR_NM") {
        $c.stf.fn_OpenDisclViewer(scwin.gAcptNo, scwin.gViewerStat);
    } else if (colid == "ACPT_DDTM") {
        $c.stf.fn_OpenDisclAllList();
    } else if (colid == "COM_ABBRV") {
        $c.stf.fn_PopupCorpInfo();
    }
};
scwin.fn_setContnId = function(obj) {
    scwin.gViewerStat = "R"; // 처리시 뷰어=P,  조회시 뷰어=R
    if (eval(obj) > 0) {
        //그리드에서 선택시
        if (MaxTab_01.getSelectedTabIndex() == 1) {
            scwin.gAcptNo = dts_List_1.getCellData(eval(obj), "ACPT_NO");
            scwin.gMainFormCd = dts_List_1.getCellData(eval(obj), "FORM_CD");
            scwin.gFormVer = dts_List_1.getCellData(eval(obj), "FORM_VER");
            scwin.gIsurCd = dts_List_1.getCellData(eval(obj), "ISUR_CD");

            //수익증권신청서는 공시3팀-->유가 공시지원TF팀 변경(2660, 20210312) 
            if (scwin.gMainFormCd == '68904' || scwin.gMainFormCd == '68905' || scwin.gMainFormCd == '68928') {
                //if (js_dep_cd == '2630') {//공시3팀
                //2021-02-22 2611 -> 2650
                //2021-03-12 2650-> 2660
                //2022-01-21 2660-> 2620
                //2024-01-26 2620-> 2611
                if (js_dep_cd == '2611' || js_dep_cd == '2600') {
                    scwin.gViewerStat = "P"; // 처리시 뷰어=P,  조회시 뷰어=R

                }
            } else {
                scwin.gViewerStat = "P"; // 처리시 뷰어=P,  조회시 뷰어=R

            }
        } else if (MaxTab_01.getSelectedTabIndex() == 2) {
            scwin.gAcptNo = dts_List_2.getCellData(eval(obj), "ACPT_NO");
            scwin.gMainFormCd = dts_List_2.getCellData(eval(obj), "FORM_CD");
            scwin.gFormVer = dts_List_2.getCellData(eval(obj), "FORM_VER");
            scwin.gIsurCd = dts_List_2.getCellData(eval(obj), "ISUR_CD");
            scwin.gApprovYn = dts_List_2.getCellData(eval(obj), "APPROVYN");
            if (scwin.gApprovYn == 'Y') {
                //유가 공시부일경우
                scwin.gViewerStat = "P"; // 처리시 뷰어=P,  조회시 뷰어=R

            }
        } else if (MaxTab_01.getSelectedTabIndex() == 3) {
            scwin.gIsurCd = dts_List_3.getCellData(eval(obj), "ISUR_CD");
        }
    }
};
scwin.fn_ExcelDown = function() {
    //엑셀 로그 
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
    if (MaxTab_01.getSelectedTabIndex() == 2) {
        //grd_List_2.GridToExcel("접수처리목록", "", "2");
        $c.data.downloadGridViewOffice(grd_List_2, "접수처리목록", "", 8, 0);
    } else if (MaxTab_01.getSelectedTabIndex() == 3) {
        //grd_List_3.GridToExcel("업무처리목록", "", "8");
        $c.data.downloadGridViewOffice(grd_List_3, "업무처리목록", "", 8, 0);
    }
};
