scwin.dts_EMP_NO_1_OnFilter = function(row) {
    //  부서코드에  해당하는 사원을 가져온다.
    if (scwin.gDepCd == "") {
        // 전체일 경우 모두 보여준다.
        return true;
    } else {
        if (dts_EMP_NO_1.getCellData(row, "DEP_CD") == scwin.gDepCd || dts_EMP_NO_1.getCellData(row, "DEP_CD") == "") {
            return true;
        } else {
            return false;
        }
    }
};
