scwin.gform_onload = function() {
    if (js_market != "9") {
        $c.cm.setColumnProp(grd_List_1, "LD_MKT_TP_NM", "Show", false);
        $c.cm.setColumnProp(grd_List_2, "LD_MKT_TP_NM", "Show", false);
        $c.cm.setColumnProp(grd_List_3, "LD_MKT_TP_NM", "Show", false);
    }
    //2020-02-14 etn, elw 조직개편 by nhkw
    if (js_dep_cd == "2B40" || js_dep_cd == "2B30") {
        $c.cm.setColumnProp(grd_List_1, "DEP_NM", "Show", false);
        $c.cm.setColumnProp(grd_List_1, "EMP_NM", "Show", false);
        $c.cm.setColumnProp(grd_List_1, "PROCS_DEP_NM", "Show", true);
        $c.cm.setColumnProp(grd_List_2, "DEP_NM", "Show", false);
        $c.cm.setColumnProp(grd_List_2, "EMP_NM", "Show", false);
        $c.cm.setColumnProp(grd_List_2, "PROCS_DEP_NM", "Show", true);
        $c.cm.setColumnProp(grd_List_3, "DEP_NM", "Show", false);
        $c.cm.setColumnProp(grd_List_3, "EMP_NM", "Show", false);
    } else {
        $c.cm.setColumnProp(grd_List_1, "DEP_NM", "Show", true);
        $c.cm.setColumnProp(grd_List_1, "EMP_NM", "Show", true);
        $c.cm.setColumnProp(grd_List_1, "PROCS_DEP_NM", "Show", false);
        $c.cm.setColumnProp(grd_List_2, "DEP_NM", "Show", true);
        $c.cm.setColumnProp(grd_List_2, "EMP_NM", "Show", true);
        $c.cm.setColumnProp(grd_List_2, "PROCS_DEP_NM", "Show", false);
        $c.cm.setColumnProp(grd_List_3, "DEP_NM", "Show", true);
        $c.cm.setColumnProp(grd_List_3, "EMP_NM", "Show", true);
    }
    MaxTab_01.setSelectedTabIndex(1);
    $c.libRoundPanel.PanelToGroupBox(panel_Top_1);
    $c.cm.PanelToGroupBox(panel_Top_2);
    $c.libRoundPanel.PanelToGroupBox(panel_Top_3);

    /* 2010.03.11 김봉석대리 요청(1927)
     *   default 2개월 
     */
    var vCurDate = $c.ut.cGetToday("yyyymmdd");
    var vCurMonth = $c.ut.cGetMinusMonth(vCurDate.substring(0, 4), vCurDate.substring(4, 6), vCurDate.substring(6, 8), 2);
    edt_AcptSDate.setValue(vCurMonth);
    edt_AcptEDate.setValue(vCurDate);
    edt_BzSDate.setValue(vCurMonth);
    edt_BzEDate.setValue(vCurDate);
    $c.stf.Combo_CBDataSetPeriod(cmb_PeriodTp_2);
    $c.stf.Combo_CBDataSetPeriod(cmb_PeriodTp_3);
    scwin.fn_SetCode();

    //CopyDataSet(dts_DEP_CD_3, dts_DEP_CD_2);
    //CopyDataSet(dts_EMP_NO_3, dts_EMP_NO_2);

    scwin.fn_Search();
};
